{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.plus_catalog_allocation_hygiene AS WITH actual_inwards AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MAX(CATEGORY) AS CATEGORY, MIN(INWARD_DATE) AS FIRST_INWARD_DATE, MAX(INWARD_DATE) AS LAST_INWARD_DATE, SUM(QTY) AS TOTAL_INWARDED_QTY FROM snitch_db.maplemonk.plus_inwards_master WHERE INWARD_TYPE = \'ACTUAL_INWARD\' GROUP BY UPPER(TRIM(SKU_GROUP)) ), catalog AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, LIVE_DATE, STATUS, FINAL_STATUS, SHOPIFY_ACTUAL_INV, UNITS_ON_HAND, CREATED_AT_DATE, CATALOGIX_SENT_TIMESTAMP, CATALOGIX_RECEIVED_TIMESTAMP FROM snitch_db.maplemonk.sku_group_sample_to_live QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(SKU_GROUP)) ORDER BY LAST_UPDATED_AT_ACTUAL DESC NULLS LAST, LAST_UPDATED_AT DESC NULLS LAST ) = 1 ) SELECT i.SKU_GROUP, i.CATEGORY, i.FIRST_INWARD_DATE, i.LAST_INWARD_DATE, i.TOTAL_INWARDED_QTY, c.CREATED_AT_DATE, c.LIVE_DATE, c.STATUS AS CATALOG_STATUS, c.FINAL_STATUS, c.CATALOGIX_SENT_TIMESTAMP, c.CATALOGIX_RECEIVED_TIMESTAMP, c.SHOPIFY_ACTUAL_INV, c.UNITS_ON_HAND, CASE WHEN c.SKU_GROUP IS NULL THEN \'INWARDED_NOT_CATALOGUED\' WHEN LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%cancel%\' THEN \'CANCELLED\' WHEN c.LIVE_DATE IS NULL AND LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%draft%\' THEN \'INWARDED_IN_DRAFT\' WHEN c.LIVE_DATE IS NOT NULL AND COALESCE(c.SHOPIFY_ACTUAL_INV, 0) = 0 THEN \'INWARDED_NOT_ALLOCATED\' ELSE \'OK\' END AS HYGIENE_STATUS, CASE WHEN c.SKU_GROUP IS NULL THEN 1 ELSE 0 END AS NOT_CATALOGUED_FLAG, CASE WHEN c.SKU_GROUP IS NOT NULL AND LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%cancel%\' THEN 1 ELSE 0 END AS CANCELLED_FLAG, CASE WHEN c.SKU_GROUP IS NOT NULL AND c.LIVE_DATE IS NULL AND LOWER(COALESCE(c.STATUS, \'\')) LIKE \'%draft%\' THEN 1 ELSE 0 END AS IN_DRAFT_FLAG, CASE WHEN c.SKU_GROUP IS NOT NULL AND c.LIVE_DATE IS NOT NULL AND COALESCE(c.SHOPIFY_ACTUAL_INV, 0) = 0 THEN 1 ELSE 0 END AS NOT_ALLOCATED_FLAG FROM actual_inwards i LEFT JOIN catalog c ON i.SKU_GROUP = c.SKU_GROUP;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            